static void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
template<class F>static void rejects(F f,const char* why){bool failed=false;try{f();}catch(const std::exception&){failed=true;}check(failed,why);}
static Reconstruction base(){Reconstruction r;r.cameras[0]=Camera::defaultFor(0,800,600,500,CamModel::Pinhole);for(uint32_t i=0;i<4;++i){Image im;im.id=i;im.camera_id=0;im.name="photo-"+std::to_string(i);im.registered=true;im.pose={mat3Identity(),{-.5*i,0,0}};im.points2D.resize(8);im.point3D_ids.assign(8,kInvalidPoint3D);r.images[i]=im;}return r;}
static void point(Reconstruction& r,uint64_t id,Vec3 truth,Vec3 xyz,std::initializer_list<TrackElement> track){Point3D p;p.xyz=xyz;p.track=track;for(auto e:track){auto& im=r.images.at(e.image_id);im.points2D[e.point2D_idx]=r.cameras[0].project(mul(im.pose.R,truth)+im.pose.t);im.point3D_ids[e.point2D_idx]=id;}r.points3D[id]=p;r.next_point3D_id=std::max(r.next_point3D_id,id+1);}
static void lruCase(const fs::path& root){
 using namespace regional::private_geometry_detail;auto a=base(),b=base();for(auto* r:{&a,&b})for(auto& im:r->images){im.second.points2D.resize(18);im.second.point3D_ids.resize(18,kInvalidPoint3D);}for(uint32_t i=0;i<18;++i){point(a,i,{.02*i,.1,8},{1,1,4},{{0,i},{1,i}});point(b,100+i,{.02*i,.1,8},{2,1,3},{{0,i},{1,i}});}auto pa=root/"lru-a.bin",pb=root/"lru-b.bin";model_store_detail::writeModel(a,pa);model_store_detail::writeModel(b,pb);Store store(root/"lru-work",128u<<20);store.importModel(pa,a);store.importModel(pb,b);Topo topo(root/"lru-topo",128u<<20);topo.prepare(store,std::vector<uint32_t>(4,0));auto dir=root/"lru-private";fs::create_directory(dir);std::vector<File> files;
 for(uint64_t g=0;g<18;++g){auto path=dir/("tracks-"+std::to_string(g)+".bin");std::ofstream out(path,std::ios::binary);for(uint64_t slot:{g,g+18})for(uint32_t image:{0u,1u})regional::record(out,Row{g,slot,(uint64_t(image)<<32)|g,a.images.at(image).points2D.at(size_t(g))});out.close();files.push_back({path.u8string(),digest(path),fs::file_size(path)});}
 constexpr uint64_t magic=0x3156505053525353ull;const auto path=dir/"cache.bin";{model_store_detail::Writer out(path);out.scalar(magic);out.string(topo.identity());out.string(topo.ownerIdentity());out.scalar<uint64_t>(2);out.string(store.sourceIdentity(0));out.string(store.sourceIdentity(1));out.vector(std::vector<uint64_t>{0,18,36});out.scalar<uint64_t>(36);for(size_t source=0;source<2;++source)for(uint64_t i=0;i<18;++i)out.scalar(store.key(source,i));out.scalar<uint64_t>(18);for(uint64_t g=0;g<18;++g)out.scalar(Group{g,0,4,g});out.scalar<uint64_t>(18);for(auto& file:files){out.string(file.path);out.string(file.hash);out.scalar(file.bytes);}out.finish();}
 {model_store_detail::Writer out(dir/"head.bin");out.scalar(magic);out.string(path.u8string());out.string(digest(path));out.finish();}Cache cache(dir,128u<<20);store.resetCounters();cache.prepare(store,topo);for(size_t g=0;g<18;++g){cache.visit(cache.groups[0],[](auto){});cache.visit(cache.groups[g],[](auto){});}cache.visit(cache.groups[0],[](auto){});check(cache.readerOpens==18&&cache.readerHits>=19,"bounded LRU reopened hot old support file after >16 cold files");check(store.counters().raw_bytes==0,"LRU derived support test reread source raw");std::cout<<"PASS: 18 immutable support files, hot old file retained by bounded true LRU, opens="<<cache.readerOpens<<" hits="<<cache.readerHits<<"\n";
}
static void edgeCases(const fs::path& root){
 auto rec=base();point(rec,0,{.2,.1,8},{1,1,-3},{{0,0},{1,0}});rec.images.at(1).points2D[0].y+=.3;point(rec,1,{.4,.2,9},{2,2,3},{{2,1},{3,1}});auto path=root/"invalid-source.bin";model_store_detail::writeModel(rec,path);Store store(root/"invalid-work",128u<<20);store.importModel(path,rec);Topo topology(root/"invalid-topo",128u<<20);topology.prepare(store,std::vector<uint32_t>(4,0));store.beginGeneration();auto q=regional::refinePrivateGeometry(store,topology,store.poses(),3,0,128u<<20,root/"invalid-private");check(q.invalid_to_valid_finite_tradeoff==1&&q.before.invalid==2&&q.after.invalid==0,"all-invalid point was silently frozen by a per-point finite gate");check(regional::privateGeometryAccepted(q)&&q.after.finite<q.before.finite,"full private stage Pareto did not govern real finite tradeoff");store.commitGeneration();
 auto a=base(),b=base();point(a,10,{0,0,8},{0,0,8},{{0,0},{1,1}});point(b,20,{0,0,12},{0,0,12},{{0,0},{2,2}});auto pa=root/"conflict-a.bin",pb=root/"conflict-b.bin";model_store_detail::writeModel(a,pa);model_store_detail::writeModel(b,pb);Store conflicting(root/"conflict-work",128u<<20);conflicting.importModel(pa,a);conflicting.importModel(pb,b);Topo incompatible(root/"conflict-topo",128u<<20);incompatible.prepare(conflicting,std::vector<uint32_t>(4,0));conflicting.beginGeneration();auto rejected=regional::refinePrivateGeometry(conflicting,incompatible,conflicting.poses(),3,2,128u<<20,root/"conflict-private");check(rejected.unresolved_alias_groups==1&&rejected.rejected==1,"incompatible private originals silently given a canonical XYZ");check((conflicting.pointXYZ(conflicting.key(0,0))-Vec3{0,0,8}).norm()==0&&(conflicting.pointXYZ(conflicting.key(1,0))-Vec3{0,0,12}).norm()==0,"rejected alias replaced original XYZ");check(fs::file_size(rejected.ledger)>100,"unresolved alias ledger absent");conflicting.abortGeneration();
 auto head=root/"conflict-private/head.bin";std::fstream bad(head,std::ios::binary|std::ios::in|std::ios::out);uint64_t wrong=0;bad.write(reinterpret_cast<const char*>(&wrong),8);bad.close();rejects([&]{Cache broken(root/"conflict-private",128u<<20);broken.prepare(conflicting,incompatible);},"corrupt support head silently rebuilt/accepted");
 // Old private support promoted by a new immutable source must be gathered once.
 auto p=base(),v=base(),w=base();point(p,0,{.2,.3,8},{1,1,4},{{0,0},{1,0}});point(p,1,{-.3,.2,7},{2,1,5},{{2,1},{3,1}});point(v,10,{.2,.3,8},{2,2,3},{{0,0},{1,0}});point(w,20,{-.3,.2,7},{1,2,4},{{2,1},{3,1}});auto pp=root/"promote-a.bin",pv=root/"promote-b.bin",pw=root/"promote-c.bin";model_store_detail::writeModel(p,pp);model_store_detail::writeModel(v,pv);model_store_detail::writeModel(w,pw);Store promotion(root/"promotion-work",128u<<20);promotion.importModel(pp,p);promotion.importModel(pv,v);Topo promoted(root/"promotion-topo",128u<<20);promoted.prepare(promotion,std::vector<uint32_t>(4,0));{Cache initial(root/"promotion-private",128u<<20);initial.prepare(promotion,promoted);}promotion.importModel(pw,w);promoted.prepare(promotion,std::vector<uint32_t>(4,0));Cache appended(root/"promotion-private",128u<<20);appended.prepare(promotion,promoted);check(appended.newRaw==4&&appended.reusedGroups==1&&appended.groups.size()==2,"promoted old private did not use selective fullraw gather/reuse oldgroup");Cache freshPromotion(root/"promotion-fresh",128u<<20);freshPromotion.prepare(promotion,promoted);
 using SupportIdentity=std::tuple<uint64_t,uint64_t,uint64_t,uint64_t,uint64_t,double,double>;auto complete=[&](Cache& cache){std::vector<SupportIdentity> rows;for(size_t g=0;g<cache.groups.size();++g)cache.visit(cache.groups[g],[&](auto row){const auto key=cache.members.at(size_t(row.slot));rows.emplace_back(row.root,key.source,key.ordinal,key.localPoint,row.feature,row.xy.x,row.xy.y);});std::sort(rows.begin(),rows.end());return rows;};check(complete(appended)==complete(freshPromotion),"promoted append/fresh original point/image/feature/XY/multiplicity support differs");
 std::cout<<"PASS: invalid-to-valid finite tradeoff with stage Pareto, incompatible alias originals+ledger preserved, corrupt cache refusal, old private promotion incremental full support\n";
}
static int run(int,char**){ModelStore tmp("");auto root=tmp.directory();auto a=base(),b=base();point(a,0,{.2,.3,8},{2,1,4},{{0,0},{1,0}});point(a,1,{-.3,.1,7},{1,2,3},{{2,1},{3,1}});point(a,2,{.5,-.1,9},{2,2,3},{{1,2},{3,2}});point(b,11,{-.3,.1,7},{2,1,4},{{2,1},{3,1}});point(b,10,{.2,.3,8},{-1,1,5},{{0,0},{1,0},{2,0},{2,0}});auto pa=root/"a.bin",pb=root/"b.bin";model_store_detail::writeModel(a,pa);model_store_detail::writeModel(b,pb);Store store(root/"work",128u<<20);store.importModel(pa,a);store.importModel(pb,b);Topo topo(root/"topo",128u<<20);std::vector<uint32_t> owners(4,0);topo.prepare(store,owners);check(topo.groups()==0,"same-owner alias incorrectly staticshared");auto aliases=topo.privateAliasRoots();check(aliases[topo.canonical(store.key(0,0))],"private alias missing");auto x0=store.pointXYZ(store.key(0,0)),x1=store.pointXYZ(store.key(0,1));uint64_t originalRaw=store.sourceObservationCount(0)+store.sourceObservationCount(1);store.beginGeneration();auto beforePoses=store.poses();auto q=regional::refinePrivateGeometry(store,topo,store.poses(),3,2,128u<<20,root/"private");check(q.before.observations==originalRaw,"fullraw duplicate coverage lost");check(q.after.invalid<=q.before.invalid&&q.after.finite<=q.before.finite&&q.after.total<=q.before.total,"private aggregate objective increased");check(q.changed>=3,"single/multialias XYZ did not change");check((store.pointXYZ(store.key(0,0))-store.pointXYZ(store.key(1,0))).norm()<1e-12,"private aliases got different accepted XYZ");check((store.pointXYZ(store.key(0,2))-Vec3{2,2,3}).norm()>1e-4,"single XYZ unrefined");check(store.poses().cameras.at(0).fx==beforePoses.cameras.at(0).fx&&store.poses().images.at(0).pose.t.x==beforePoses.images.at(0).pose.t.x,"fixed cameras/poses mutated");store.commitGeneration();
 {Cache cache(root/"private",128u<<20);store.resetCounters();cache.prepare(store,topo);check(store.counters().raw_bytes==0&&cache.newRaw==0,"warm private cache reread raw");uint64_t rows=0;for(size_t g=0;g<cache.groups.size();++g)cache.visit(cache.groups[g],[&](auto){++rows;});check(rows==10,"cached aliases normalized/dropped duplicate raw");}
 {std::set<uint32_t> none;store.beginGeneration();store.resetCounters();auto empty=regional::refinePrivateGeometry(store,topo,store.poses(),3,2,128u<<20,root/"private",&none);check(empty.visited==0&&empty.before.observations==0&&store.counters().raw_bytes==0,"empty affected round readraw/retriangulated points");store.commitGeneration();}
 auto c=base();point(c,20,{.2,.3,8},{2,2,3},{{0,0},{3,0}});auto pc=root/"c.bin";model_store_detail::writeModel(c,pc);store.importModel(pc,c);topo.prepare(store,owners);
 {Cache append(root/"private",128u<<20);store.resetCounters();append.prepare(store,topo);check(append.newRaw==2&&append.reusedGroups==1,"append rescanned old alias raw or lost unchanged support");Cache fresh(root/"fresh",128u<<20);fresh.prepare(store,topo);check(append.groups.size()==fresh.groups.size(),"append group count differs");std::vector<regional::private_geometry_detail::Row> aa,bb;for(size_t g=0;g<append.groups.size();++g)append.visit(append.groups[g],[&](auto row){aa.push_back(row);});for(size_t g=0;g<fresh.groups.size();++g)fresh.visit(fresh.groups[g],[&](auto row){bb.push_back(row);});check(aa.size()==bb.size()&&aa.size()==12,"append complete raw support differs");for(size_t i=0;i<aa.size();++i)check(aa[i].root==bb[i].root&&aa[i].feature==bb[i].feature&&aa[i].xy.x==bb[i].xy.x&&aa[i].xy.y==bb[i].xy.y,"append/fresh raw feature identity differs");}
 auto accepted=store.pointXYZ(store.key(0,0));store.beginGeneration();rejects([&]{regional::refinePrivateGeometry(store,topo,store.poses(),3,2,8u<<20,root/"private",nullptr,[&](const auto&){throw std::runtime_error("cancel test");});},"callback cancellation swallowed");store.abortGeneration();check((store.pointXYZ(store.key(0,0))-accepted).norm()==0,"cancel changed accepted XYZ");
 edgeCases(root);lruCase(root);std::cout<<"PASS: raw duplicates, initial single/multi-alias calibration, fixed P/K, warm zero raw scan, append/fresh exact support, empty round zero raw, cancellation rollback\n";return 0;}
int main(int argc,char**argv){return sfmTestMain(argc,argv,run);}
